extern uint32_t lean_fs_manifest_validate(size_t addr, size_t n);
extern uint32_t lean_fs_manifest_scan(size_t addr, size_t n);
extern size_t lean_fs_manifest_find_key(size_t addr, size_t n, size_t key, size_t key_len);
extern size_t lean_fs_manifest_value_off(size_t addr, size_t n, size_t key_off);
extern size_t lean_fs_manifest_value_len(size_t addr, size_t n, size_t key_off);
