    /* ArenaPool smokes (remaining, pure alloc, slot bump, full, reset) */
    {
      uint8_t buf[16];
      size_t used = 0;
      size_t p;
      if (lean_fs_arena_pool_remaining(16, 0) != 16)
        return 820;
      if (lean_fs_arena_pool_remaining(16, 16) != 0)
        return 821;
      if (lean_fs_arena_pool_can_alloc(16, 0, 8) != 0)
        return 822;
      if (lean_fs_arena_pool_can_alloc(16, 10, 8) != 3)
        return 823;
      if (lean_fs_arena_pool_alloc_end(16, 0, 4) != 4)
        return 824;
      if (lean_fs_arena_pool_alloc_end(16, 14, 4) != (size_t)-1)
        return 825;
      p = lean_fs_arena_pool_alloc_addr((size_t)(uintptr_t)buf, 16, 0, 4);
      if (p != (size_t)(uintptr_t)buf)
        return 826;
      if (lean_fs_arena_pool_reset((size_t)(uintptr_t)&used) != 0)
        return 827;
      if (lean_fs_arena_pool_load_used((size_t)(uintptr_t)&used) != 0)
        return 828;
      p = lean_fs_arena_pool_alloc((size_t)(uintptr_t)buf, 16, (size_t)(uintptr_t)&used, 5);
      if (p != (size_t)(uintptr_t)buf || used != 5)
        return 829;
      p = lean_fs_arena_pool_alloc((size_t)(uintptr_t)buf, 16, (size_t)(uintptr_t)&used, 5);
      if (p != (size_t)(uintptr_t)(buf + 5) || used != 10)
        return 830;
      if (lean_fs_arena_pool_alloc((size_t)(uintptr_t)buf, 16, (size_t)(uintptr_t)&used, 10)
          != (size_t)-1)
        return 831;
      if (lean_fs_arena_pool_alloc_status((size_t)(uintptr_t)buf, 16, (size_t)(uintptr_t)&used, 6)
          != 0)
        return 832;
      if (used != 16)
        return 833;
      if (lean_fs_arena_pool_alloc_status((size_t)(uintptr_t)buf, 16, (size_t)(uintptr_t)&used, 1)
          != 3)
        return 834;
      if (lean_fs_arena_pool_reset((size_t)(uintptr_t)&used) != 0 || used != 0)
        return 835;
      /* zero-size alloc at capacity succeeds without growth */
      used = 16;
      p = lean_fs_arena_pool_alloc((size_t)(uintptr_t)buf, 16, (size_t)(uintptr_t)&used, 0);
      if (p != (size_t)(uintptr_t)(buf + 16) || used != 16)
        return 836;
      printf("arena_pool: ok\n");
    }

