      uint8_t reply[] = {'2', '5', '0', ' ', 'O', 'K', '\n'};
      if (lean_fs_smtp_validate((size_t)(uintptr_t)reply, 7) != 0)
        return 3030;
      if (lean_fs_smtp_parse((size_t)(uintptr_t)reply, 7) != 0)
        return 3031;
      if (lean_fs_smtp_is_reply((size_t)(uintptr_t)reply, 7) != 1u)
        return 3032;
      if (lean_fs_smtp_code((size_t)(uintptr_t)reply, 7) != 250u)
        return 3033;
      if (lean_fs_smtp_method_len((size_t)(uintptr_t)reply, 7) != 0)
        return 3034;
      if (lean_fs_smtp_text_off((size_t)(uintptr_t)reply, 7) != 4)
        return 3035;
      if (lean_fs_smtp_has_text((size_t)(uintptr_t)reply, 7) != 1u)
        return 3036;
