      if (lean_fs_smtp_validate((size_t)(uintptr_t)reply, 3) != 1)
        return 3047;
      if (lean_fs_smtp_parse((size_t)(uintptr_t)reply, 0) != 1)
        return 3048;
      if (lean_fs_smtp_is_reply((size_t)(uintptr_t)reply, 2) != 0u)
        return 3049;
      if (lean_fs_smtp_code((size_t)(uintptr_t)reply, 2) != 0u)
        return 3050;
