      if (lean_fs_roaring_insert((size_t)(uintptr_t)keys, RCAP, RCAP + 1, 1u) != 3)
        return 3177;
      if (lean_fs_roaring_insert((size_t)(uintptr_t)keys, 0, 0, 1u) != 3)
        return 3178;
      if (lean_fs_roaring_is_full(0, 0) != 1)
        return 3179;
      /* remove middle; siblings must remain (not clear) */
      if (lean_fs_roaring_remove((size_t)(uintptr_t)keys, rn, 20u) != 0)
        return 3180;
      rn = 3;
      if (lean_fs_roaring_contains((size_t)(uintptr_t)keys, rn, 20u) != 0)
        return 3181;
      if (lean_fs_roaring_contains((size_t)(uintptr_t)keys, rn, 10u) != 1)
        return 3182;
      if (lean_fs_roaring_contains((size_t)(uintptr_t)keys, rn, 30u) != 1)
        return 3183;
      if (lean_fs_roaring_contains((size_t)(uintptr_t)keys, rn, 40u) != 1)
        return 3184;
      if (lean_fs_roaring_get((size_t)(uintptr_t)keys, rn, 0) != 10)
        return 3185;
      if (lean_fs_roaring_get((size_t)(uintptr_t)keys, rn, 1) != 30)
        return 3186;
      if (lean_fs_roaring_get((size_t)(uintptr_t)keys, rn, 2) != 40)
        return 3187;
      if (lean_fs_roaring_remove((size_t)(uintptr_t)keys, rn, 99u) != 1)
        return 3188;
      if (lean_fs_roaring_remove((size_t)(uintptr_t)keys, 0, 1u) != 1)
        return 3189;
      printf("roaring_lite: ok\n");
