    if (lean_fs_proc_pipe(0) != 1u)
      return 6040;
    if (lean_fs_proc_pipe((size_t)(uintptr_t)ends) != 0u)
      return 6041;
    if ((ssize_t)ends[0] < 0 || (ssize_t)ends[1] < 0)
      return 6042;
    /* distinct read/write ends */
    if (ends[0] == ends[1])
      return 6043;

    argv_echo[0] = (size_t)(uintptr_t)"echo";
    argv_echo[1] = (size_t)(uintptr_t)"hi";
    argv_echo[2] = (size_t)(uintptr_t)0; /* unused; argc=2 */
    /* child stdout → write end; parent keeps read end */
    pid = lean_fs_proc_spawn_argv_pipe((size_t)(uintptr_t)"/bin/echo",
                                       (size_t)(uintptr_t)argv_echo, 2,
                                       (size_t)-1, ends[1]);
    if (lean_fs_proc_pid_is_neg(pid) != 0u)
      return 6044;
    /* close write end in parent so read sees EOF after child exits */
    if (lean_fs_proc_close_raw(ends[1]) != 0u)
      return 6045;
    memset(rbuf, 0, sizeof rbuf);
    nr = lean_fs_read(ends[0], (size_t)(uintptr_t)rbuf, sizeof rbuf - 1);
    if ((ssize_t)nr < 0)
      return 6046;
    if (nr < 2 || rbuf[0] != 'h' || rbuf[1] != 'i')
      return 6047;
    st = lean_fs_proc_wait(pid);
    if (st != 0u)
      return 6048;
    if (lean_fs_close(ends[0]) != 0u)
      return 6049;

